@startuml

class Product {
  + Name : string
  + Description : string
  + NetPrice : double
}

class Country {
  + Name : string
  + VATRate : double
  + Currency : string
  + ConversionRateToEuro : double
}

class Representative {
  + FirstName : string
  + LastName : string
  + Ssn : int
  + TelephoneNumber : string
  + EmailAddress : string
}

class Customer {
  + Name : string
  + Address : string
  + TelephoneNumber : string
  + EmailAddress : string
}

class Order {
  + OrderID : string
  + Quantity : int
  + OrderDate : date
  + DesiredDeliveryDate : date
}

class Manufacturer {
  + Name : string
}

Product "*" -- "1" Manufacturer : manufacturedBy
Product "*" -- "1" Country : producedIn
Product "*" -- "0..*" Country : availableIn
Representative "1" -- "1" Country : responsibleFor
Customer "1" -- "0..*" Country : resellsIn
Representative "1" -- "0..*" Order : places
Order "*" -- "1" Product : refersTo
Order "*" -- "1" Customer : placedBy

@enduml

